from collections import Counter


def analyse(log):
    lines = [l for l in log.splitlines() if l.strip()]
    errors = [l.split(" ", 1)[1] for l in lines if l.startswith("ERROR ")]
    top = Counter(errors).most_common(1)[0][0] if errors else None
    return {"total": len(lines), "errors": len(errors), "top_error": top}

alt:
def analyse(log):
    total = 0
    counts = {}
    n_errors = 0
    for line in log.splitlines():
        if not line.strip():
            continue
        total += 1
        if line.startswith("ERROR "):
            n_errors += 1
            msg = line[6:]
            counts[msg] = counts.get(msg, 0) + 1
    top = max(counts, key=counts.get) if counts else None
    return {"total": total, "errors": n_errors, "top_error": top}
